begin;
create function pg_temp.expect(ok boolean,label text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'AUTH WORKER TEST: %',label;end if;end$$;
create function pg_temp.denied(q text) returns boolean language plpgsql as $$begin execute q;return false;exception when insufficient_privilege then return true;end$$;
insert into auth.users values('aaaaaaaa-0000-0000-0000-000000000099','service@machine.test'),('bbbbbbbb-0000-0000-0000-000000000098','member@machine.test');
insert into private.machine_identities(sub) values('aaaaaaaa-0000-0000-0000-000000000099');
insert into public.app_members(email) values('member@machine.test');
insert into public.google_mailbox_connections(email,refresh_token_encrypted,refresh_token_iv,refresh_token_tag) values('member@machine.test','synthetic','synthetic','synthetic');
insert into public.relationship_sync(member_email,enabled) values('member@machine.test',true);
insert into public.crm_sync_accounts(email) values('member@machine.test');
create temp table owned_lease(id uuid,lease uuid);grant all on owned_lease to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"bbbbbbbb-0000-0000-0000-000000000098","email":"member@machine.test"}',true);
select pg_temp.expect(pg_temp.denied('select public.worker_claim_sync()'),'member cannot claim');
select pg_temp.expect(pg_temp.denied('select public.worker_sync_context(gen_random_uuid(),gen_random_uuid())'),'member cannot get credentials');
select pg_temp.expect(pg_temp.denied('select public.worker_commit_sync(gen_random_uuid(),gen_random_uuid(),''[]'',''{}'',true)'),'member cannot publish');
select pg_temp.expect(pg_temp.denied('select public.worker_commit_drive(gen_random_uuid(),gen_random_uuid(),''[]'',''{}'',true)'),'member cannot publish Drive');
select pg_temp.expect(pg_temp.denied('select public.worker_fail_sync(gen_random_uuid(),gen_random_uuid(),''unavailable'')'),'member cannot fail job');
select pg_temp.expect(pg_temp.denied('select public.worker_signal_gmail(''x@machine.test'',''1'')'),'member cannot signal');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"bbbbbbbb-0000-0000-0000-000000000099","email":"unregistered@machine.test"}',true);
select pg_temp.expect(pg_temp.denied('select public.worker_claim_sync()'),'unregistered authenticated subject denied');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"aaaaaaaa-0000-0000-0000-000000000099","email":"service@machine.test"}',true);
select pg_temp.expect(not private.is_member(),'service excluded from app membership');
select pg_temp.expect(pg_temp.denied('select * from private.machine_identities'),'service cannot inspect registry');
select pg_temp.expect(pg_temp.denied('insert into private.machine_identities(sub) values(gen_random_uuid())'),'service cannot register another subject');
-- Assert actual RLS results, not role grants (authenticated grants are shared by members).
do $$declare t record;n bigint;changed bigint;column_name text;begin
 for t in select n.nspname,c.relname,c.oid,c.relkind from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','storage') and c.relkind in ('r','p','v','m') loop
  begin execute format('select count(*) from %I.%I',t.nspname,t.relname) into n;perform pg_temp.expect(n=0,'service read isolation '||t.relname);exception when insufficient_privilege then null;end;
  if t.nspname in ('public','storage') then
   select attname into column_name from pg_attribute where attrelid=t.oid and attnum>0 and not attisdropped and attidentity='' and attgenerated='' order by attnum limit 1;
   if column_name is not null then
    begin execute format('update %I.%I set %I=%I',t.nspname,t.relname,column_name,column_name);get diagnostics changed=row_count;perform pg_temp.expect(changed=0,'service write isolation '||t.relname);exception when insufficient_privilege or feature_not_supported or object_not_in_prerequisite_state then null;end;
   end if;
   begin execute format('delete from %I.%I',t.nspname,t.relname);get diagnostics changed=row_count;perform pg_temp.expect(changed=0,'service delete isolation '||t.relname);exception when insufficient_privilege or feature_not_supported or object_not_in_prerequisite_state then null;end;
   if t.relkind in ('r','p') then perform pg_temp.expect(not has_table_privilege('authenticated',t.oid,'TRUNCATE'),'no RLS-bypassing truncate grant '||t.relname);end if;
  end if;
 end loop;
end$$;
select pg_temp.expect(pg_temp.denied('insert into public.people(name) values(''Forbidden service Person'')'),'service insert denied');
select pg_temp.expect(pg_temp.denied('select public.lp_ensure_board()'),'service cannot use member UI RPC');
insert into owned_lease select id,lease from public.worker_claim_sync();
select pg_temp.expect((select count(*)=1 from owned_lease),'registered service can claim relationships-only work');
select pg_temp.expect((public.worker_sync_context((select id from owned_lease),(select lease from owned_lease))->>'publishRelationships')::boolean,'service receives relationship sink');
select pg_temp.expect(pg_temp.denied('select public.worker_signal_gmail(''x@machine.test'',''1'')'),'push remains disabled for service');
reset role;
update private.machine_identities set enabled=false;
set local role authenticated;
select pg_temp.expect(pg_temp.denied('select public.worker_claim_sync()'),'revocation blocks claim');
select pg_temp.expect(pg_temp.denied('select public.worker_sync_context((select id from owned_lease),(select lease from owned_lease))'),'revocation blocks old lease context');
select pg_temp.expect(pg_temp.denied('select public.worker_commit_sync((select id from owned_lease),(select lease from owned_lease),''[]'',''{}'',true)'),'revocation blocks old lease commit');
select pg_temp.expect(pg_temp.denied('select public.worker_fail_sync((select id from owned_lease),(select lease from owned_lease),''unavailable'')'),'revocation blocks fail');
select pg_temp.expect((select count(*)=0 from public.app_members),'revoked service still sees no members');
reset role;
update private.machine_identities set enabled=true;
update public.crm_sync_accounts set enabled=true;
set local role authenticated;
select pg_temp.expect(pg_temp.denied('select public.worker_claim_sync()'),'relationships-only identity fails before processing enabled CRM');
reset role;
update public.crm_sync_accounts set enabled=false;
update private.machine_identities set tokens_valid_after='2026-01-01';
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"aaaaaaaa-0000-0000-0000-000000000099","email":"service@machine.test","iat":1}',true);
select pg_temp.expect(pg_temp.denied('select public.worker_claim_sync()'),'old signed access token rejected after rotation fence');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"aaaaaaaa-0000-0000-0000-000000000099","email":"service@machine.test","iat":2000000000}',true);
select count(*) from public.worker_claim_sync();
reset role;
set local role vanquish_worker;
select pg_temp.expect(pg_temp.denied('select public.worker_claim_sync()'),'legacy machine role no longer claims');
reset role;
rollback;
